from http.server import BaseHTTPRequestHandler, HTTPServer
import socketserver
from urllib.parse import urlparse, parse_qs
import win32com.client
import time

'''
a web service wrapper for the FKPID com interface to enable the FKPID to remain enabled between tests
http://127.0.0.1:6803/?command=connected  	- checks connection
http://127.0.0.1:6803/?command=start		- starts beam
http://127.0.0.1:6803/?command=interrupt	- interrups beam
http://127.0.0.1:6803/?command=asu	        - asu linac

'''

class HttpFkpidListener(BaseHTTPRequestHandler):


    fkpid_com = win32com.client.Dispatch("Elekta.RT.Linac.AutomatedSetup.FkpInterfaceDeviceController")

    while not fkpid_com.Connected:

        fkpid_com.FindDevice()
        time.sleep(1)
        fkpid_com.ErrorReset()
        time.sleep(1)
        fkpid_com.StartWatchdogResetTimer()
        time.sleep(1)
        fkpid_com.Authorize(True)
        print("Press enable button on FKpid - Active LED shoud light")
        print("State is "+ str(fkpid_com.GetState()))

        # Headers to read FKPID responses
        def set_headers(self):
            self.send_response(201)
            self.send_header('Content-type','text-html')
            self.end_headers()

    def do_GET(self):
        print("Received : " + self.path)
        query = urlparse(self.path).query
        params = parse_qs(query)
        print(params)
        command = params['command']
        print("command: " + command[0])

        if "start" in command:
            self.send_response(201, str(self.fkpid_com.StartMegavoltageRadiation(True,500)))
            self.end_headers()

        elif "stop" in command:
            self.send_response(201, str(self.fkpid_com.StartMegavoltageRadiation(False,500)))
            self.end_headers()

        elif "interrupt" in command:
            self.send_response(201, str(self.fkpid_com.InterruptMegavoltageRadiation(True,500)))
            self.end_headers()

        elif "reset" in command:
            self.fkpid_com.ErrorReset()
            self.send_response(201, str(self.fkpid_com.Authorize(True)))
            self.end_headers()

        elif "connected" in command:

            self.set_headers()
            self.wfile.write(bytes(self.fkpid_com.Connected))
        elif "asu_start" in command:
            self.send_response(201, str(self.fkpid_com.EnableAsu(False)))
            time.sleep(1)
            self.send_response(201, str(self.fkpid_com.EnableAsu(True)))
            time.sleep(1)
            self.send_response(201, str(self.fkpid_com.EnableLinacAsu(True)))
            self.end_headers()
        elif "asu_stop" in command:
            self.send_response(201, str(self.fkpid_com.EnableLinacAsu(False)))
            time.sleep(1)
            self.send_response(201, str(self.fkpid_com.EnableAsu(False)))
            self.end_headers()
        elif "check_fkpid_state" in command:
            self.set_headers()
            print("State is "+ str(self.fkpid_com.GetState()))
        elif "get_error_code" in command:
            self.set_headers()
            print("Error code is "+ str(self.fkpid_com.GetErrorCode()))
        elif "deauthorize" in command:
            self.set_headers()
            self.fkpid_com.Authorize(False)
        elif "disconnect" in command:
            self.set_headers()
            self.fkpid_com.Disconnect()
        else:
            self.send_error(401, "invalid command")



def run():
    server_address = ('', 6804)
    httpd = HTTPServer(server_address, HttpFkpidListener)
    print('Starting Http FKPID server...')
    print ("Minimize this window, do not close")
    httpd.serve_forever()


if __name__ == "__main__":
    run()

def main():
    run()